def chain_of_following(chain):
    tokens = list(chain)
    result = []
    current = tokens[0]
    for i in range(len(tokens)):
        next_token = tokens[i+1]
        if next_token == current:
            result.append(current)
            current = next_token
        else:
            result.append(current)
            current = next_token
    return ','.join(result)

